 etk=[('Tansiyon ve şeker ilaçları', 'Tansiyonu ve kan şekerini düşürebilir.'), ('Parkinson ilaçları', 'Sinir sistemi üzerindeki etkileri hastalığı kötüleştirebilir.')],
